python - <<'PY'
from pathlib import Path
import re
path = Path('/scratch/result.py')
text = path.read_text()
pattern = re.compile(r"def _write_report\(path: Path, best: dict\[str, Any\], ranked: list\[dict\[str, Any\]\], donor_table: pd.DataFrame\) -> None:\n.*?path\.write_text\(\"\\n\"\.join\(lines\), encoding=\"utf-8\"\)\n", re.S)
replacement = '''def _write_report(path: Path, best: dict[str, Any], ranked: list[dict[str, Any]], donor_table: pd.DataFrame) -> None:\n    feature_col = best["feature_column"]\n    per_donor = pd.DataFrame(best["per_donor_loo"]).merge(\n        donor_table[\n            [\n                "donor_id",\n                feature_col,\n                "ca1_pyramidal_n",\n                "ca1_reactive_astrocyte_n",\n                "ca1_corpora_amylacea_n",\n                "reactive_niche_pyramidal_n",\n            ]\n        ],\n        on="donor_id",\n        how="left",\n    )\n    per_donor["abs_error"] = (per_donor["outcome"] - per_donor["predicted"]).abs()\n    per_donor["signed_error"] = per_donor["predicted"] - per_donor["outcome"]\n    worst = per_donor.sort_values("abs_error", ascending=False).head(5).copy()\n    worst_ids = worst["donor_id"].astype(str).tolist()\n\n    nonzero_worst = worst.loc[worst[feature_col] > 0, ["donor_id", feature_col, "ca1_corpora_amylacea_n", "reactive_niche_pyramidal_n"]]\n    if nonzero_worst.empty:\n        worst_trait_text = "Most of the worst-error donors still had zero-valued corpora-positive niche fractions, so the model mainly missed donors with severe decline despite no detectable corpora-amylacea-positive reactive niche by this definition."\n    else:\n        parts = []\n        for _, row in nonzero_worst.iterrows():\n            parts.append(\n                f\"{row['donor_id']} (feature={_format_num(row[feature_col])}, CA count={int(row['ca1_corpora_amylacea_n'])}, reactive-niche pyramidal n={int(row['reactive_niche_pyramidal_n'])})\"\n            )\n        worst_trait_text = \"Among the worst-error donors, the ones with nonzero corpora-positive niche signal were \" + \", \".join(parts) + \".\"\n\n    underpred_ids = worst.loc[worst["predicted"] > worst["outcome"], "donor_id"].astype(str).tolist()\n    overpred_ids = worst.loc[worst["predicted"] <= worst["outcome"], "donor_id"].astype(str).tolist()\n    direction_text = (\n        f\"The worst misses were mostly underestimates of decline for {', '.join(underpred_ids)}\"\n        if underpred_ids\n        else \"The worst misses were not dominated by one prediction direction\"\n    )\n    if overpred_ids:\n        direction_text += f\", with overestimates for {', '.join(overpred_ids)}.\"\n    else:\n        direction_text += \".\"\n\n    other_lines = []\n    for item in ranked[1:]:\n        other_lines.append(\n            f\"- {item['name']} ({item['radius_px']} px): partial_r={_format_num(item['partial_r'])}, \"\n            f\"selection_score={_format_num(item['selection_score'])}, \"\n            f\"loo_r={_format_num(item['loo_predictive_r'])}, adjusted={_format_num(item['adjusted_score'])}\"\n        )\n    other_text = \"\\n\".join(other_lines) if other_lines else \"- No alternative variations.\"\n\n    radii_sorted = sorted(item[\"radius_px\"] for item in ranked)\n    if best[\"radius_px\"] == min(radii_sorted):\n        failed_reason = (\n            f\"Broader corpora-amylacea radii underperformed, suggesting the signal is most specific at the tightest \"\n            f\"CA1 reactive-neuron debris niche scale rather than in a wider neighborhood.\"\n        )\n        next_suggestion = (\n            f\"Stay in the same CA1 reactive-neuron/corpora family and test still tighter corpora radii around the \"\n            f\"{best['radius_px']} px winner, or switch from any-neighbor to local corpora count per reactive-niche neuron.\"\n        )\n    elif best[\"radius_px\"] == max(radii_sorted):\n        failed_reason = (\n            f\"Narrower corpora-amylacea radii underperformed, suggesting the relevant degenerative-debris field extends \"\n            f\"beyond the immediate neuron surface and is only captured at a broader CA1 reactive niche scale.\"\n        )\n        next_suggestion = (\n            f\"Stay in the same family and test slightly broader corpora radii beyond {best['radius_px']} px, or an \"\n            f\"intensity variant using mean corpora neighbor count among reactive-niche pyramidal neurons.\"\n        )\n    else:\n        failed_reason = (\n            f\"Both the tighter and broader corpora-amylacea radii were weaker, implying the family is locally specific: \"\n            f\"too small likely misses the reactive-debris halo, while too large dilutes the niche with broader CA1 background.\"\n        )\n        next_suggestion = (\n            f\"Keep the same CA1 reactive-neuron/corpora family but next sweep nearby summaries around the \"\n            f\"{best['radius_px']} px scale, such as corpora neighbor count or corpora-only density conditioned on the same reactive-niche denominator.\"\n        )\n\n    sparsity_note = (\n        f\"The winning feature is sparse in this cohort: only {(donor_table[feature_col] > 0).sum()} of {len(donor_table)} donors had a nonzero value, so the family behaves more like a rare-niche marker than a broad continuum.\"\n    )\n\n    lines = [\n        \"## Summary\",\n        f\"Tested the {FEATURE_FAMILY} family in CA1 reactive-astrocyte-conditioned pyramidal niches; {best['name']} won with selection_score={_format_num(best['selection_score'])}.\",\n        \"\",\n        \"## Metrics\",\n        f\"Best variation: {best['name']} ({best['radius_px']} px).\",\n        f\"- IS partial r: {_format_num(best['partial_r'])}\",\n        f\"- Selection score: {_format_num(best['selection_score'])}\",\n        f\"- LOO predictive r: {_format_num(best['loo_predictive_r'])}\",\n        f\"- IS-LOO Gap: {_format_num(best['is_loo_gap'])} (penalty={_format_num(best['gap_penalty'])})\",\n        f\"- Adjusted Score: {_format_num(best['adjusted_score'])}\",\n        f\"- n_analyzable / n_total: {best['n_analyzable']} / {best['n_total']}\",\n        \"Other tested variations:\",\n        other_text,\n        \"\",\n        \"## Findings\",\n        f\"1. What worked and why: The winning signal comes from {TARGET_REGION} {FOCAL_LABEL.lower()}s that already sit in {REACTIVE_LABEL.lower()} neighborhoods, then asks how often those neurons also have nearby {CORPORA_LABEL.lower()}. That conditional denominator focuses the feature on a chronic-debris version of the existing CA1 injury niche rather than global corpora burden, which is biologically coherent if local degenerative debris handling tracks more advanced neuronal stress. {sparsity_note}\",\n        f\"2. What failed and why: {failed_reason}\",\n        f\"3. Error pattern: The largest LOO misses were donors {', '.join(worst_ids)}. {direction_text} {worst_trait_text}\",\n        \"\",\n        \"## Rationale\",\n        f\"The best variation is biologically coherent because it measures a specific CA1 microenvironment: pyramidal neurons near reactive astrocytes, further stratified by whether corpora amylacea are also present nearby. That is a plausible marker of chronic local tissue stress or debris-processing burden, distinct from pure neuron loss, reactive burden alone, or oligodendrocyte absence. It beat the nearby alternatives because its radius better matched the apparent spatial scale of corpora amylacea accumulation around injured CA1 neuronal niches.\",\n        \"Relative to the current accepted panel, this candidate seems only moderately likely to add new information because the panel already captures CA1 neuron-loss and reactive-niche biology; any additivity would have to come from a more chronic debris-handling axis rather than another restatement of the same CA1 injury process.\",\n        \"\",\n        \"## Interpretation\",\n        f\"The signal appears to mean that faster memory decline tracks {TARGET_REGION} neuronal niches where {REACTIVE_LABEL.lower()}s and {CORPORA_LABEL.lower()} co-occur around {FOCAL_LABEL.lower()}s.\",\n        f\"- Population: {TARGET_REGION} {FOCAL_LABEL}\",\n        f\"- Niche: {TARGET_REGION} reactive-astrocyte-exposed pyramidal neighborhoods\",\n        f\"- Feature summary: fraction of reactive-niche CA1 pyramidal neurons with at least one {CORPORA_LABEL} within {best['radius_px']} px\",\n        f\"- Simplest observable pattern: CA1 pyramidal zones already touching reactive astrocytes that also show nearby corpora amylacea / chronic degenerative debris bodies\",\n        \"\",\n        \"## Next\",\n        next_suggestion,\n        \"\",\n    ]\n    path.write_text(\"\\n\".join(lines), encoding=\"utf-8\")\n'''
new_text, n = pattern.subn(replacement, text)
if n != 1:
    raise SystemExit(f'replaced {n} blocks, expected 1')
path.write_text(new_text)
print('patched _write_report')
PY
